// Sync API for practice stats. Static app files are served by the assets binding;
// only /api/* reaches this code (see run_worker_first in wrangler.jsonc).
//
//   GET    /api/sync/:code             -> { devices: { [deviceId]: { name, updated, stats } } }
//   PUT    /api/sync/:code/:deviceId   body { name, stats } -> same as GET, after saving
//
// A sync code is 12 Crockford base32 characters (60 random bits) generated by the app.
// Only its SHA-256 is stored. Each device writes only its own row.

interface StatRecord {
  c: number;
  w: number;
  h: string;
  t: number;
}

interface DeviceEntry {
  name: string;
  updated: number;
  stats: Record<string, StatRecord>;
}

const CODE = /^[0-9A-HJKMNP-TV-Z]{12}$/;
const DEVICE_ID = /^[a-z0-9]{4,32}$/;
const QUESTION_ID = /^[A-Za-z0-9_-]{1,40}$/;
const HISTORY = /^[01]{0,10}$/;
const MAX_QUESTIONS = 5000;
const MAX_NAME = 40;

export class HttpError extends Error {
  constructor(readonly status: number, message: string) {
    super(message);
  }
}

// Accept codes as typed by people: any case, with dashes or spaces, O for 0 and I/L for 1.
export function normaliseCode(raw: string): string {
  const code = raw.toUpperCase().replace(/[\s-]/g, '').replace(/O/g, '0').replace(/[IL]/g, '1');
  if (!CODE.test(code)) throw new HttpError(400, 'Invalid sync code');
  return code;
}

async function hashCode(code: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(code));
  return [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('');
}

function isCount(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 1e13;
}

export function validateBody(body: unknown): { name: string; stats: Record<string, StatRecord> } {
  if (!body || typeof body !== 'object') throw new HttpError(400, 'Body must be a JSON object');
  const { name, stats } = body as { name?: unknown; stats?: unknown };
  if (name !== undefined && (typeof name !== 'string' || name.length > MAX_NAME)) {
    throw new HttpError(400, `name must be a string of at most ${MAX_NAME} characters`);
  }
  if (!stats || typeof stats !== 'object' || Array.isArray(stats)) throw new HttpError(400, 'stats must be an object');
  const entries = Object.entries(stats);
  if (entries.length > MAX_QUESTIONS) throw new HttpError(400, 'Too many questions in stats');
  const clean: Record<string, StatRecord> = {};
  for (const [qid, r] of entries) {
    const rec = r as Partial<StatRecord> | null;
    if (!QUESTION_ID.test(qid) || !rec || typeof rec !== 'object'
      || !isCount(rec.c) || !isCount(rec.w) || !isCount(rec.t)
      || typeof rec.h !== 'string' || !HISTORY.test(rec.h)) {
      throw new HttpError(400, `Invalid stats entry for ${qid.slice(0, 40)}`);
    }
    clean[qid] = { c: rec.c, w: rec.w, h: rec.h, t: rec.t };
  }
  return { name: (name as string | undefined) ?? '', stats: clean };
}

async function readDevices(env: Env, codeHash: string): Promise<Record<string, DeviceEntry>> {
  const { results } = await env.DB
    .prepare('SELECT device_id, name, updated_at, stats FROM devices WHERE code_hash = ?')
    .bind(codeHash)
    .all<{ device_id: string; name: string; updated_at: number; stats: string }>();
  const devices: Record<string, DeviceEntry> = {};
  for (const row of results) {
    devices[row.device_id] = { name: row.name, updated: row.updated_at, stats: JSON.parse(row.stats) };
  }
  return devices;
}

async function readJson(request: Request, maxBytes: number): Promise<unknown> {
  const declared = Number(request.headers.get('content-length') || 0);
  if (declared > maxBytes) throw new HttpError(413, 'Body too large');
  const text = await request.text();
  if (new TextEncoder().encode(text).length > maxBytes) throw new HttpError(413, 'Body too large');
  try {
    return JSON.parse(text);
  } catch {
    throw new HttpError(400, 'Body is not valid JSON');
  }
}

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      'x-content-type-options': 'nosniff',
    },
  });
}

async function handleSync(request: Request, env: Env, parts: string[]): Promise<Response> {
  const ip = request.headers.get('cf-connecting-ip') || 'unknown';
  const { success } = await env.SYNC_LIMITER.limit({ key: ip });
  if (!success) throw new HttpError(429, 'Too many requests, try again in a minute');

  const [rawCode, deviceId, ...rest] = parts;
  if (!rawCode || rest.length) throw new HttpError(404, 'Not found');
  const codeHash = await hashCode(normaliseCode(decodeURIComponent(rawCode)));

  if (deviceId === undefined) {
    if (request.method !== 'GET') throw new HttpError(405, 'Method not allowed');
    return json({ devices: await readDevices(env, codeHash) });
  }
  if (!DEVICE_ID.test(deviceId)) throw new HttpError(400, 'Invalid device id');

  if (request.method === 'PUT') {
    const { name, stats } = validateBody(await readJson(request, Number(env.MAX_BODY_BYTES)));
    const existing = await env.DB
      .prepare('SELECT device_id FROM devices WHERE code_hash = ?')
      .bind(codeHash)
      .all<{ device_id: string }>();
    const known = existing.results.some(r => r.device_id === deviceId);
    if (!known && existing.results.length >= Number(env.MAX_DEVICES_PER_CODE)) {
      throw new HttpError(409, 'This sync code already has the maximum number of devices');
    }
    await env.DB
      .prepare(`INSERT INTO devices (code_hash, device_id, name, updated_at, stats) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT (code_hash, device_id) DO UPDATE SET
                  name = excluded.name, updated_at = excluded.updated_at, stats = excluded.stats`)
      .bind(codeHash, deviceId, name, Date.now(), JSON.stringify(stats))
      .run();
    return json({ devices: await readDevices(env, codeHash) });
  }
  throw new HttpError(405, 'Method not allowed');
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const parts = url.pathname.split('/').filter(Boolean);
    try {
      if (parts[0] === 'api' && parts[1] === 'sync') return await handleSync(request, env, parts.slice(2));
      if (parts[0] === 'api') throw new HttpError(404, 'Not found');
      return env.ASSETS.fetch(request);
    } catch (e) {
      if (e instanceof HttpError) return json({ error: e.message }, e.status);
      console.error(e);
      return json({ error: 'Internal error' }, 500);
    }
  },
} satisfies ExportedHandler<Env>;
